int genl_register_family(struct genl_family *family)
{
    int err;
    struct genl_family *existing_family;

    if (!family || !family->name || family->version < 0 || family->module == NULL)
        return -EINVAL;

    mutex_lock(&genl_mutex);

    existing_family = genl_find_family(family->name);
    if (existing_family)
        return -EEXIST;

    if (family->id != GENL_ID_ALLOC) {
        if (family->id < GENL_RESERVED_START || family->id >= GENL_MAX_ID)
            return -EINVAL;
        if (genl_families[family->id])
            return -EBUSY;
    }

    if (family->n_attrs) {
        family->attr_policy = kcalloc(family->n_attrs,
                                      sizeof(struct nla_policy),
                                      GFP_KERNEL);
        if (!family->attr_policy) {
            err = -ENOMEM;
            goto out;
        }
    }

    err = genl_assign_family_id(family);
    if (err < 0)
        goto out;

    if (family->mcgrps) {
        int i;

        for (i = 0; i < family->n_mcgrps; i++) {
            if (!family->mcgrps[i].name || family->mcgrps[i].id >= GENL_MCGRP_MAX)
                return -EINVAL;
        }
    }

    list_add_tail(&family->list, &genl_families_list);

    mutex_unlock(&genl_mutex);

    err = genl_notify_family_registered(family);
    if (err < 0) {
        genl_unregister_family(family);
        return err;
    }

    return 0;

out:
    mutex_unlock(&genl_mutex);
    return err;
}

int genl_register_family(struct genl_family *family) {
    int err = 0;

    if (!family || !family->ops)
        return -EINVAL;

    if (family->id != GENL_ID_GENERATE) {
        if (family->id >= GENL_ID_MAX)
            return -EINVAL;
    }

    mutex_lock(&genl_mutex);

    if (genl_fam_get_by_name(family->name)) {
        mutex_unlock(&genl_mutex);
        return -EEXIST;
    }

    if (!family->id) {
        family->id = genl_get_free_id();
        if (!family->id) {
            mutex_unlock(&genl_mutex);
            return -ENOSPC;
        }
    }

    if (family->n_attrs) {
        family->attr_policy = kzalloc(family->n_attrs * sizeof(struct nla_policy), GFP_KERNEL);
        if (!family->attr_policy) {
            err = -ENOMEM;
            goto err_out;
        }
    }

    err = genl_register_ops(family, family->ops);
    if (err)
        goto err_out;

    list_add(&family->list, &genl_families);

    mutex_unlock(&genl_mutex);

    genl_notify_family_registered(family);

    return 0;

err_out:
    if (family->attr_policy)
        kfree(family->attr_policy);
    mutex_unlock(&genl_mutex);
    return err;
}

int genl_register_family(struct genl_family *family)
{
    int err;

    if (!family || !family->n_ops || !family->name)
        return -EINVAL;

    if (family->id != GENL_ID_INVALID) {
        if (family->id >= GENL_ID_MIN && family->id <= GENL_ID_MAX)
            return -EINVAL;
    }

    down_write(&genl_mutex);

    if (family_find(family->name)) {
        up_write(&genl_mutex);
        return -EEXIST;
    }

    if (!family->hdrsize)
        family->hdrsize = GENL_HDRLEN;

    if (family->mcgrps && family->n_mcgrps) {
        int i;
        for (i = 0; i < family->n_mcgrps; i++) {
            if (!family->mcgrps[i].name)
                goto err;
        }
    }

    family->id = genl_get_unique_id();
    if (family->id < 0) {
        err = family->id;
        goto err;
    }

    if (family->n_attrs && family->attrpolicy) {
        family->attrs = kcalloc(family->n_attrs, sizeof(void *), GFP_KERNEL);
        if (!family->attrs) {
            err = -ENOMEM;
            goto err;
        }
    }

    list_add_tail(&family->list, &genl_fam_list);

    up_write(&genl_mutex);

    genl_notify_family_added(family);
    genl_notify_mc_groups(family);

    return 0;

err:
    up_write(&genl_mutex);
    return err;
}

int genl_register_family(struct genl_family *family) {
    int err;

    if (!family)
        return -EINVAL;

    if (!family->ops || family->n_ops == 0) {
        return -EINVAL;
    }

    for (int i = 0; i < family->n_ops; i++) {
        struct genl_ops *op = &family->ops[i];
        if (!op->doit && !op->dumpit)
            return -EINVAL;
    }

    write_lock_bh(&genl_family_lock);

    if (genl_find_family(family->name)) {
        write_unlock_bh(&genl_family_lock);
        return -EEXIST;
    }

    if (family->id == 0) {
        err = genl_get_family_id(family);
        if (err < 0) {
            write_unlock_bh(&genl_family_lock);
            return err;
        }
    } else if (family->id < GENL_ID_MIN || family->id > GENL_ID_MAX) {
        write_unlock_bh(&genl_family_lock);
        return -EINVAL;
    }

    if (family->n_attrs > 0) {
        family->attrs = kcalloc(family->n_attrs, sizeof(void *), GFP_KERNEL);
        if (!family->attrs) {
            write_unlock_bh(&genl_family_lock);
            return -ENOMEM;
        }
    }

    for (int i = 0; i < family->n_mcgrps; i++) {
        struct genl_multicast_group *grp = &family->mcgrps[i];
        if (!grp->name || !grp->maxattr) {
            kfree(family->attrs);
            write_unlock_bh(&genl_family_lock);
            return -EINVAL;
        }
        if (grp->id >= GENL_MCAST_MAX) {
            kfree(family->attrs);
            write_unlock_bh(&genl_family_lock);
            return -EINVAL;
        }
    }

    list_add(&family->list, &genl_family_list);

    write_unlock_bh(&genl_family_lock);

    err = genl_notify_family(family, GENL_EVENT_ADD);
    if (err < 0) {
        write_lock_bh(&genl_family_lock);
        list_del(&family->list);
        write_unlock_bh(&genl_family_lock);
        kfree(family->attrs);
        return err;
    }

    for (int i = 0; i < family->n_mcgrps; i++) {
        struct genl_multicast_group *grp = &family->mcgrps[i];
        err = genl_notify_mcgrp(family, grp, GENL_EVENT_ADD);
        if (err < 0) {
            write_lock_bh(&genl_family_lock);
            list_del(&family->list);
            write_unlock_bh(&genl_family_lock);
            kfree(family->attrs);
            return err;
        }
    }

    return 0;
}

int genl_register_family(struct genl_family *family) {
    int err;
    struct genl_family *existing_family;

    if (!family || !family->name || family->version < 0 || family->maxattr < 0)
        return -EINVAL;

    mutex_lock(&genl_mutex);

    existing_family = genl_find_family(family->id);
    if (existing_family)
        if (strcmp(existing_family->name, family->name) == 0)
        {
            mutex_unlock(&genl_mutex);
            return -EEXIST;
        }

    if (family->id == GENL_ID_CTRL)
    {
        if (strcmp(family->name, "controller") != 0)
        {
            mutex_unlock(&genl_mutex);
            return -EINVAL;
        }
    }

    if (family->n_attrs && !family->ops)
    {
        family->ops = kcalloc(family->n_attrs, sizeof(*family->ops), GFP_KERNEL);
        if (!family->ops)
        {
            mutex_unlock(&genl_mutex);
            return -ENOMEM;
        }
    }

    family->id = genl_get_id(family);
    if (family->id < 0)
    {
        kfree(family->ops);
        mutex_unlock(&genl_mutex);
        return family->id;
    }

    err = validate_multicast_groups(family);
    if (err)
    {
        kfree(family->ops);
        mutex_unlock(&genl_mutex);
        return err;
    }

    list_add_tail(&family->list, &genl_families);

    mutex_unlock(&genl_mutex);

    genl_notify_family_registered(family);

    return 0;
}
